// probe.test.js — probe temporaire du playtesteur (supprimée à la livraison).
// Les cas vivent ensuite dans .scratch/to_fix.md. Logique pure, sans DOM.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import {
  step,
  createState,
  ballSpeed,
  collides,
  HEIGHT,
  BALL_R,
  BRICK_W,
  BRICK_H,
  BRICK_GAP,
  PADDLE_Y,
  PADDLE_W,
  PADDLE_H,
} from '../game/neon.js';

const DT = 1 / 60;
const DT_MAX = 0.05;
const EPS = 1e-9;

// D2 — le coin doit ressortir par les DEUX axes (le miroir "sortie" du cas angle).
describe('coin sortie', () => {
  test('coin haut gauche: la balle ressort du rectangle sur les deux axes', () => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };
    step(state, DT);
    assert.ok(state.ball.x + BALL_R <= 100 + EPS, `bord droit x <= 100 : ${state.ball.x + BALL_R}`);
    assert.ok(state.ball.y + BALL_R <= 100 + EPS, `bord bas y <= 100 : ${state.ball.y + BALL_R}`);
  });
});

// D3 — après le rebond de couture, la balle ne recouvre plus AUCUNE des deux briques.
describe('couture sortie', () => {
  test('couture horizontale: la balle ressort, les deux briques ne recouvrent plus', () => {
    const state = createState(1);
    state.bricks = [
      { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
      { x: 100 + BRICK_W + BRICK_GAP, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
    ];
    state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };
    step(state, DT);
    assert.ok(state.ball.vy > 0, `un seul rebond : ${state.ball.vy}`);
    assert.ok(state.ball.y - BALL_R >= 100 - EPS, `ressortie par le bas : ${state.ball.y - BALL_R}`);
    assert.ok(!collides(state.ball, state.bricks[0]), 'plus de recouvrement brique 1');
    assert.ok(!collides(state.ball, state.bricks[1]), 'plus de recouvrement brique 2');
  });
});

// D4 — traversée : le même saut donne le même résultat quel que soit le dt
// (invariant dépendance à dt : 30 fps vs 144 fps).
describe('traversee dt', () => {
  const brique = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
  const ball = (dt) => {
    const s = createState(6);
    s.bricks = [{ ...brique }];
    s.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    step(s, dt);
    return s;
  };
  test('dt = 0.05 : la brique est touchée et la balle rebondit', () => {
    const s = ball(DT_MAX);
    assert.ok(!s.bricks[0].alive, 'brique non détruite');
    assert.ok(s.ball.vy > 0, `vy devait rebondir : ${s.ball.vy}`);
  });
  test('dt = 0.04 : la brique est touchée et la balle rebondit', () => {
    const s = ball(0.04);
    assert.ok(!s.bricks[0].alive, 'brique non détruite');
    assert.ok(s.ball.vy > 0, `vy devait rebondir : ${s.ball.vy}`);
